//! Worldgen P25 contract-frontier admission contract.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const FEATURE_ID:&str="AFA-worldgen-P25-F01";pub const CONTRACT_VERSION:&str="worldgen-local-contract-frontier/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.contract-frontier-receipt-1+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct FrontierCandidate4{pub candidate_id:String,pub capability_id:String,pub version:String,pub novelty_score_milli:u32,pub support_score_milli:u32,pub evidence_state:String,pub schema_digest:ContentHash,pub provenance_digest:ContentHash,pub replay_identity:ContentHash,pub consumer:String,pub local:bool,pub aggregate_only:bool,pub negative_result:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ContractFrontierRequest4{pub request_id:String,pub scope:String,pub benchmark_id:String,pub candidates:Vec<FrontierCandidate4>,pub required_capability_order:Vec<String>,pub min_novelty_milli:u32,pub min_support_milli:u32,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub network_available:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub action_budget:u32,pub action_count:u32,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ContractFrontierArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub candidate_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ContractFrontierCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub benchmark_id:String,pub disposition:String,pub candidate_order:Vec<String>,pub selected_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub uncertainty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub capability_order:Vec<String>,pub schema_digest_order:Vec<ContentHash>,pub provenance_digest_order:Vec<ContentHash>,pub replay_identity:ContentHash,pub frontier_digest:ContentHash,pub artifact:ContractFrontierArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ContractFrontierError{#[error("invalid contract-frontier request: {0}")]Invalid(String),#[error("contract-frontier card failed validation: {0}")]Output(String)}
fn ord(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn dig(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ne(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":id,"version":version,"owner_crate":"worldgen","consumers":["frontier steward","research scientist","schema maintainer","release operator"],"behavior":format!("admit versioned contract-frontier candidates at {scale} ({mode})"),"value":"turns novelty and support claims into auditable, typed, replayable capability admission decisions","input_schema":"ContractFrontierRequest4@1","output_schema":"ContractFrontierCard7@1","effects":["emit:frontier-card","block:unsafe-release"],"permissions":["read:local-capability-candidates"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
impl ContractFrontierCard7{pub fn validate(&self)->Result<(),ContractFrontierError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||!ne(&self.benchmark_id)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.candidate_order.is_empty()||!ord(&self.candidate_order)||!ord(&self.selected_order)||!ord(&self.rejected_order)||!ord(&self.unknown_order)||!ord(&self.omitted_order)||!ord(&self.uncertainty_order)||!ord(&self.negative_evidence_order)||!ord(&self.capability_order)||!self.schema_digest_order.iter().all(dig)||!self.provenance_digest_order.iter().all(dig)||!dig(&self.replay_identity)||!dig(&self.frontier_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.frontier_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY||!self.effect_receipts.iter().all(|e|e.starts_with("emit:frontier-card:")||e=="block:unsafe-release"){return Err(ContractFrontierError::Output("frontier identity, ordering, locality, digest, or effect is invalid".into()))}let ids=BTreeSet::from_iter(self.candidate_order.iter().cloned());let parts=self.selected_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.candidate_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(ContractFrontierError::Output("candidate states do not partition".into()))}Ok(())}}
pub fn admit(request:&ContractFrontierRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<ContractFrontierCard7,ContractFrontierError>{if !ne(&request.request_id)||!ne(&request.scope)||!ne(&request.benchmark_id)||request.candidates.is_empty()||request.required_capability_order.is_empty()||request.min_novelty_milli>1000||request.min_support_milli>1000||!dig(&request.replay_identity)||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_capability_order)||!ord(&request.adversarial_events){return Err(ContractFrontierError::Invalid("frontier identity, thresholds, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.candidates.clone();rows.sort_by(|a,b|a.candidate_id.cmp(&b.candidate_id));let mut seen=BTreeSet::new();let mut candidates=Vec::new();let mut selected=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut capabilities=BTreeSet::new();let mut schemas=BTreeSet::new();let mut provenance=BTreeSet::new();for c in &rows{if !seen.insert(c.candidate_id.clone())||!ne(&c.candidate_id)||!ne(&c.capability_id)||!ne(&c.version)||c.novelty_score_milli>1000||c.support_score_milli>1000||!ne(&c.consumer)||!dig(&c.schema_digest)||!dig(&c.provenance_digest)||!dig(&c.replay_identity){return Err(ContractFrontierError::Invalid("candidate identity, score, consumer, or digest is invalid".into()))}candidates.push(c.candidate_id.clone());capabilities.insert(c.capability_id.clone());schemas.insert(c.schema_digest.clone());provenance.insert(c.provenance_digest.clone());if c.negative_result{negative.insert(format!("{}:negative-result",c.candidate_id));}if c.replay_identity!=request.replay_identity||!c.local||!c.aggregate_only{omitted.insert(c.candidate_id.clone());}else if c.evidence_state=="unknown"||c.evidence_state=="unmeasured"{unknown.insert(c.candidate_id.clone());}else if c.evidence_state=="contradicted"{rejected.insert(c.candidate_id.clone());uncertainty.insert(format!("{}:contradicted",c.candidate_id));}else if c.evidence_state=="proven"||c.evidence_state=="supported"{if c.novelty_score_milli>=request.min_novelty_milli&&c.support_score_milli>=request.min_support_milli{selected.insert(c.candidate_id.clone());}else{rejected.insert(c.candidate_id.clone());uncertainty.insert(format!("{}:threshold",c.candidate_id));}}else{unknown.insert(c.candidate_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.network_available||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||(mode=="research copilot"&&(request.action_budget==0||request.action_count>request.action_budget));if global{omitted.extend(candidates.iter().cloned());selected.clear();rejected.clear();unknown.clear();}let required=BTreeSet::from_iter(request.required_capability_order.iter().cloned());let chosen_cap=rows.iter().filter(|c|selected.contains(&c.candidate_id)).map(|c|c.capability_id.clone()).collect::<BTreeSet<_>>();let disposition=if global{"blocked"}else if !request.signed_approval&&mode!="inference"{"approval_required"}else if required.is_subset(&chosen_cap)&&!selected.is_empty()&&rejected.is_empty()&&unknown.is_empty()&&omitted.is_empty(){"qualified"}else if !selected.is_empty(){"unresolved"}else{"unknown"};let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"benchmark_id":request.benchmark_id,"disposition":disposition,"candidate_order":candidates,"selected_order":selected.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"capability_order":capabilities.into_iter().collect::<Vec<_>>(),"schema_digest_order":schemas.into_iter().collect::<Vec<_>>(),"provenance_digest_order":provenance.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|ContractFrontierError::Output(e.to_string()))?;payload["frontier_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-contract-frontier:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["omitted_order"],"candidate_digests":payload["schema_digest_order"],"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:frontier-card:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:ContractFrontierCard7=serde_json::from_value(payload).map_err(|e|ContractFrontierError::Output(e.to_string()))?;out.validate()?;Ok(out)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn q()->ContractFrontierRequest4{ContractFrontierRequest4{request_id:"frontier:req".into(),scope:"study:local".into(),benchmark_id:"bench:1".into(),candidates:vec![FrontierCandidate4{candidate_id:"cand:a".into(),capability_id:"cap:a".into(),version:"1.0".into(),novelty_score_milli:900,support_score_milli:900,evidence_state:"supported".into(),schema_digest:h("schema"),provenance_digest:h("prov"),replay_identity:h("replay"),consumer:"researcher".into(),local:true,aggregate_only:true,negative_result:false}],required_capability_order:vec!["cap:a".into()],min_novelty_milli:700,min_support_milli:700,policy_allowed:true,protected_closure:true,signed_approval:true,network_available:true,raw_data_local:true,aggregate_only:true,replay_identity:h("replay"),adversarial_events:vec![],action_budget:2,action_count:1,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified(){assert_eq!(admit(&q(),FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"qualified")}#[test]fn unknown_unresolved(){let mut x=q();x.candidates[0].evidence_state="unknown".into();assert_eq!(admit(&x,FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"unknown")}#[test]fn policy_blocks(){let mut x=q();x.policy_allowed=false;assert_eq!(admit(&x,FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"blocked")}}
